"""Original single-serving bakery, breakfast and dessert recipes."""
import json
from pathlib import Path

recipes = []

def add(slug, name, description, minutes, ingredients, steps, tip, tags, motif, toppings,
        category='snack', cuisine='洋菓子', difficulty=2, equipment='ボウル,オーブン,オーブンシート',
        base='cake', vessel='plate', colors=None, garnish=''):
    recipes.append({
        'id': 'r-' + slug, 'name': name, 'description': description,
        'category': category, 'cuisine': cuisine, 'difficulty': difficulty,
        'rarity': {1:'common', 2:'rare', 3:'special'}[difficulty],
        'minutes': minutes, 'servings': 1,
        'ingredients': [{'name': pair.split(':',1)[0], 'amount': pair.split(':',1)[1]}
                        for pair in ingredients.split(';')],
        'steps': steps.split('|'), 'tip': tip, 'tags': tags.split(','),
        'equipment': equipment.split(','), 'reward': {1:20, 2:40, 3:70}[difficulty],
        'art': {'vessel': vessel, 'base': base,
                'colors': colors or ['#c58a42','#f3dda9','#774329','#24624b'],
                'garnish': garnish.split(',') if garnish else [],
                'motif': motif, 'toppings': toppings.split(',')}
    })

